paragraphs.pre:
function midpoint(f, a, b, n):
    dx = (b-a)/n
    total = 0
    for i = 1 to n:
        xmid = a + (i - 0.5)*dx
        total = total + f(xmid)
    return dx*total

function trapezoid(f, a, b, n):
    dx = (b-a)/n
    total = 0.5*f(a) + 0.5*f(b)
    for i = 1 to n-1:
        x = a + i*dx
        total = total + f(x)
    return dx*total

function simpson(f, a, b, n):
    if n is odd:
        stop with message "Simpson's Rule requires even n"
    dx = (b-a)/n
    total = f(a) + f(b)
    for i = 1 to n-1:
        x = a + i*dx
        if i is odd:
            total = total + 4*f(x)
        else:
            total = total + 2*f(x)
    return dx*total/3
